using DSAExperimentation.Algorithms.Backtracking;
namespace DSAExperimentation.Tests.LeetCodeCoverage.CombinationSumIII;
public sealed partial class CombinationSumIIITests { [Theory] [InlineData(3,7,new[]{1,2,4})] [InlineData(3,9,new[]{1,2,6})] public void CombinationSum3_Examples_ContainsExpected(int k,int n,int[] expected){var combos=Find(k,n);Assert.Contains(combos,c=>c.SequenceEqual(expected));} private static List<List<int>> Find(int k,int n){var results=new List<List<int>>();var s=new State();Backtrack.Search<State,int>(s,x=>x.Values.Count==k&&x.Sum==n,x=>x.Values.Count==k||x.Sum>=n?[]:Enumerable.Range(x.Start,10-x.Start).Where(v=>x.Sum+v<=n),(x,v)=>{x.Starts.Push(x.Start);x.Values.Add(v);x.Sum+=v;x.Start=v+1;},(x,v)=>{x.Start=x.Starts.Pop();x.Sum-=v;x.Values.RemoveAt(x.Values.Count-1);},x=>results.Add([..x.Values]));return results;} private sealed class State{public List<int> Values{get;}=[];public Stack<int> Starts{get;}=new();public int Sum{get;set;}public int Start{get;set;}=1;} }
